<a href="<?= e(route_url('/admin/reviews')) ?>" class="text-link small muted" style="margin-bottom:22px"><?= icon('arrow-left',15) ?> Back to reviews</a><div class="page-header"><div><span class="eyebrow">AN ANSWER DESERVES A THOUGHTFUL RESPONSE</span><h1><?= e($attempt['title']) ?></h1><p><?= e($attempt['full_name']) ?> · Attempt #<?= (int)$attempt['id'] ?> · <?= niceDate($attempt['submitted_at']) ?></p></div><?= badge($attempt['status']) ?></div><div class="two-column"><section class="card form-card"><form action="<?= e(route_url('/api/admin/quiz-reviews/' . ((int)$attempt['id']))) ?>" method="post" data-api data-confirm="Finalise these grades? The score is calculated from question points, and a passing result may earn eligible XP."><?= csrfField() ?><?php foreach($responses as $i=>$r): ?><section class="review-prompt"><span class="question-type"><?= e($r['type']) ?> · <?= (int)$r['points'] ?> possible points</span><h3 style="margin-top:10px"><?= $i+1 ?>. <?= e($r['prompt']) ?></h3><?php if($r['type']==='short'): ?><div class="review-response"><?= e($r['answer_text']?:'No written answer.') ?></div><?php if($attempt['status']==='pending_review'): ?><div class="field"><label for="points-<?= (int)$r['id'] ?>">Points awarded</label><input id="points-<?= (int)$r['id'] ?>" name="grades[<?= (int)$r['id'] ?>][points]" type="number" min="0" max="<?= (int)$r['points'] ?>" required></div><div class="field"><label for="feedback-<?= (int)$r['id'] ?>">Helpful feedback</label><textarea id="feedback-<?= (int)$r['id'] ?>" name="grades[<?= (int)$r['id'] ?>][feedback]" maxlength="3000"></textarea></div><?php else: ?><p class="fine-print">Awarded <?= e($r['awarded_points']) ?> points. <?= e($r['feedback']) ?></p><?php endif; ?><?php else: ?><p class="fine-print">Automatically graded on submission: <?= e($r['awarded_points']) ?> / <?= (int)$r['points'] ?> points.</p><?php endif; ?></section><?php endforeach; ?><?php if($attempt['status']==='pending_review'): ?><div class="form-actions"><button class="btn btn-primary">Finalise reviewed result <?= icon('check',16) ?></button></div><?php endif; ?></form></section><aside class="stack"><div class="notice info"><?= icon('shield',18) ?><p>Scores are recalculated from saved question responses on the server. The learner’s final result remains pending until every written response has a grade.</p></div><?php if($currentUser['role']==='administrator'): ?><section class="card form-card"><h2 class="form-section-title">Assign a reviewer.</h2><p class="form-section-description">Only authorised assigned reviewers or administrators can grade this attempt.</p><form action="<?= e(route_url('/api/admin/assign-reviewer/quiz/' . ((int)$attempt['id']))) ?>" method="post" data-api><?= csrfField() ?><div class="field"><label for="reviewer-id">Reviewer</label><select id="reviewer-id" name="reviewer_id"><?php foreach($reviewers as $r): ?><option value="<?= (int)$r['id'] ?>" <?= $r['id']===$attempt['assigned_reviewer_id']?'selected':'' ?>><?= e($r['full_name']) ?></option><?php endforeach; ?></select></div><button class="btn btn-secondary btn-block">Assign reviewer</button></form></section><?php endif; ?></aside></div>
